import assert from 'node:assert/strict';
import test from 'node:test';
import {createBalanceClient} from './src/client.mjs';
import {singleFlight} from './src/pending.mjs';
import {resolveBalance} from './src/resolve.mjs';

test('same tenant and account share only the in-flight request', async () => {
  let calls = 0;
  let finish;
  const get = createBalanceClient((tenant, account) => {
    calls++;
    assert.deepEqual([tenant, account], ['tenant', 'account']);
    return new Promise(resolve => { finish = resolve; });
  });

  const first = get('tenant', 'account');
  const concurrent = get('tenant', 'account');
  assert.ok(first instanceof Promise);
  assert.strictEqual(concurrent, first);

  await Promise.resolve();
  assert.equal(calls, 1);
  finish({balanceMinor: 42, currency: 'EUR'});
  assert.deepEqual(await first, {balanceMinor: 42, currency: 'EUR'});

  const later = get('tenant', 'account');
  assert.notStrictEqual(later, first);
  await Promise.resolve();
  assert.equal(calls, 2);
  finish({balanceMinor: 43, currency: 'EUR'});
  assert.deepEqual(await later, {balanceMinor: 43, currency: 'EUR'});
});

test('tenant/account pairs remain independent, including pairs containing colons', async () => {
  const calls = [];
  const get = createBalanceClient((tenant, account) => {
    calls.push([tenant, account]);
    return {balanceMinor: calls.length, currency: 'JPY'};
  });

  const requests = [
    get('tenant-a', 'shared'),
    get('tenant-b', 'shared'),
    get('tenant-a', 'other'),
    get('a:b', 'c'),
    get('a', 'b:c'),
  ];
  assert.equal(new Set(requests).size, requests.length);
  assert.deepEqual(await Promise.all(requests), [1, 2, 3, 4, 5].map(balanceMinor => ({balanceMinor, currency: 'JPY'})));
  assert.deepEqual(calls, [
    ['tenant-a', 'shared'],
    ['tenant-b', 'shared'],
    ['tenant-a', 'other'],
    ['a:b', 'c'],
    ['a', 'b:c'],
  ]);
});

test('a rejection is shared while pending and a later call retries', async () => {
  const failure = new Error('load failed');
  let calls = 0;
  const get = createBalanceClient(() => {
    calls++;
    return calls === 1 ? Promise.reject(failure) : {balanceMinor: 7, currency: 'GBP'};
  });

  const first = get('tenant', 'account');
  assert.strictEqual(get('tenant', 'account'), first);
  await assert.rejects(first, error => error === failure);
  assert.equal(calls, 1);
  assert.deepEqual(await get('tenant', 'account'), {balanceMinor: 7, currency: 'GBP'});
  assert.equal(calls, 2);
});

test('synchronous loader throws become rejected Promises and can be retried', async () => {
  const failure = new Error('synchronous failure');
  let calls = 0;
  const get = createBalanceClient(() => {
    if (++calls === 1) throw failure;
    return {balanceMinor: 0, currency: 'CAD'};
  });

  const first = get('tenant', 'account');
  assert.ok(first instanceof Promise);
  assert.strictEqual(get('tenant', 'account'), first);
  await assert.rejects(first, error => error === failure);
  assert.deepEqual(await get('tenant', 'account'), {balanceMinor: 0, currency: 'CAD'});
  assert.equal(calls, 2);
});

test('singleFlight keeps its exported key-and-arguments interface', async () => {
  const load = singleFlight((left, right) => `${left}/${right}`);
  const first = load('key', 'left', 'right');
  assert.strictEqual(load('key', 'ignored', 'arguments'), first);
  assert.equal(await first, 'left/right');
});

test('resolveBalance preserves zero, negative and large integer minor units and currency', async () => {
  for (const [balanceMinor, currency] of [[0, 'JPY'], [-750, 'EUR'], [Number.MAX_SAFE_INTEGER, 'KWD']]) {
    assert.deepEqual(
      await resolveBalance(() => ({balanceMinor, currency}), 'tenant', 'account'),
      {tenant: 'tenant', account: 'account', balanceMinor, currency},
    );
  }
});

test('resolveBalance propagates client failures', async () => {
  const failure = new Error('client failed');
  await assert.rejects(resolveBalance(() => { throw failure; }, 't', 'a'), error => error === failure);
  await assert.rejects(resolveBalance(() => Promise.reject(failure), 't', 'a'), error => error === failure);
});

