export function singleFlight(load) {
  const pending = new Map();
  return (key, ...args) => {
    if (pending.has(key)) return pending.get(key);

    // Defer the call so even a synchronous throw rejects the shared Promise.
    const promise = Promise.resolve().then(() => load(...args));
    pending.set(key, promise);
    const clear = () => {
      if (pending.get(key) === promise) pending.delete(key);
    };
    // Both handlers fulfill; an ignored cleanup Promise cannot reject.
    promise.then(clear, clear);
    return promise;
  };
}

