export function singleFlight(load) {
  const pending = new Map();
  return (key, ...args) => {
    if (pending.has(key)) return pending.get(key);

    // Invoke the loader in the Promise chain so synchronous throws reject p.
    const p = Promise.resolve().then(() => load(...args));
    pending.set(key, p);
    const clear = () => {
      if (pending.get(key) === p) pending.delete(key);
    };
    // Handle both outcomes; a rejected promise returned by finally would be unhandled.
    p.then(clear, clear);
    return p;
  };
}

