  const client = createBalanceClient((tenant, account) => {
    calls.push([tenant, account]);
    return requests.get(JSON.stringify([tenant, account])).promise;
  });
  const pairs = [
    ['a:b', 'c'],
    ['a', 'b:c'],
    ['tenant-a', 'same'],
    ['tenant-b', 'same'],
    ['left', 'right'],
    ['right', 'left'],
  ];
  for (const pair of pairs) requests.set(JSON.stringify(pair), deferred());

  const pending = pairs.map(([tenant, account]) => client(tenant, account));
  assert.ok(pending.every((promise) => promise instanceof Promise));
  assert.equal(client(...pairs[0]), pending[0]);
  assert.equal(new Set(pending).size, pairs.length);
  await Promise.resolve();
  assert.deepEqual(calls, pairs);

