import assert from 'node:assert/strict';
import test from 'node:test';
import {createBalanceClient} from '../src/client.mjs';
import {singleFlight} from '../src/pending.mjs';
import {resolveBalance} from '../src/resolve.mjs';

function deferred() {
  let resolve;
  let reject;
  const promise = new Promise((res, rej) => {
    resolve = res;
    reject = rej;
  });
  return {promise, resolve, reject};
}

test('only concurrent requests for the same ordered pair share a Promise', async () => {
  const calls = [];
  const requests = new Map();
  const client = createBalanceClient((tenant, account) => {
    calls.push([tenant, account]);
    return requests.get(JSON.stringify([tenant, account])).promise;
  });
  const pairs = [
    ['a:b', 'c'],
    ['a', 'b:c'],
    ['tenant-a', 'same'],
    ['tenant-b', 'same'],
    ['left', 'right'],
    ['right', 'left'],
  ];
  for (const pair of pairs) requests.set(JSON.stringify(pair), deferred());

  const pending = pairs.map(([tenant, account]) => client(tenant, account));
  assert.ok(pending.every((promise) => promise instanceof Promise));
  assert.equal(client(...pairs[0]), pending[0]);
  assert.equal(new Set(pending).size, pairs.length);
  await Promise.resolve();
  assert.deepEqual(calls, pairs);

  for (const pair of pairs) requests.get(JSON.stringify(pair)).resolve(pair.join('/'));
  assert.deepEqual(await Promise.all(pending), pairs.map((pair) => pair.join('/')));

  const next = client(...pairs[0]);
  assert.notEqual(next, pending[0]);
  assert.equal(await next, 'a:b/c');
  assert.deepEqual(calls.at(-1), pairs[0]);
});

test('rejection clears the pending request and propagates without an unhandled rejection', async () => {
  const attempts = [];
  const client = createBalanceClient(() => {
    const request = deferred();
    attempts.push(request);
    return request.promise;
  });
  const first = client('tenant', 'account');
  assert.equal(client('tenant', 'account'), first);
  await Promise.resolve();
  assert.equal(attempts.length, 1);

  const failure = new Error('service unavailable');
  attempts[0].reject(failure);
  await assert.rejects(first, (error) => error === failure);

  const second = client('tenant', 'account');
  assert.notEqual(second, first);
  await Promise.resolve();
  assert.equal(attempts.length, 2);
  attempts[1].resolve({balanceMinor: 4, currency: 'EUR'});
  assert.deepEqual(await second, {balanceMinor: 4, currency: 'EUR'});
});

test('plain values and synchronous throws both produce Promises and permit reloads', async () => {
  let attempts = 0;
  const failure = new Error('sync failure');
  const get = singleFlight((tenant, account) => {
    assert.deepEqual([tenant, account], ['t', 'a']);
    attempts++;
    if (attempts === 1) throw failure;
    return {balanceMinor: 0, currency: 'JPY'};
  });

  const first = get('key', 't', 'a');
  assert.ok(first instanceof Promise);
  assert.equal(get('key', 't', 'a'), first);
  await assert.rejects(first, (error) => error === failure);

  const second = get('key', 't', 'a');
  assert.notEqual(second, first);
  assert.deepEqual(await second, {balanceMinor: 0, currency: 'JPY'});
  assert.equal(attempts, 2);

  const third = get('key', 't', 'a');
  assert.notEqual(third, second);
  assert.deepEqual(await third, {balanceMinor: 0, currency: 'JPY'});
  assert.equal(attempts, 3);
});

test('resolveBalance keeps zero, negative and large integer minor units and source currency', async () => {
  const balances = [
    {balanceMinor: 0, currency: 'EUR'},
    {balanceMinor: -3701, currency: 'JPY'},
    {balanceMinor: Number.MAX_SAFE_INTEGER, currency: 'GBP'},
  ];
  for (const balance of balances) {
    const client = createBalanceClient(() => balance);
    assert.deepEqual(await resolveBalance(client, 'tenant', 'account'), {
      tenant: 'tenant',
      account: 'account',
      ...balance,
    });
  }
});

test('resolveBalance propagates client errors', async () => {
  const failure = new Error('lookup failed');
  await assert.rejects(
    resolveBalance(createBalanceClient(() => { throw failure; }), 'tenant', 'account'),
    (error) => error === failure,
  );
});

